const c="lc_ebbinghaus_problems";function s(e=new Date){const r=e.getFullYear(),t=String(e.getMonth()+1).padStart(2,"0"),a=String(e.getDate()).padStart(2,"0");return`${r}-${t}-${a}`}async function o(){try{const r=(await chrome.storage.local.get([c]))[c]||[],t=s();let a=0;for(const n of r)n.nextReviewDate<=t&&n.lastReviewedDate!==t&&(a+=1);a>0?(await chrome.action.setBadgeText({text:String(a)}),await chrome.action.setBadgeBackgroundColor({color:"#ef4444"})):(await chrome.action.setBadgeText({text:""}),await chrome.action.setBadgeBackgroundColor({color:"#10b981"}))}catch(e){console.error("Failed to update badge:",e)}}chrome.runtime.onInstalled.addListener(()=>{chrome.alarms.create("ebbinghaus-badge-refresh",{periodInMinutes:30}),o()});chrome.alarms.onAlarm.addListener(e=>{e.name==="ebbinghaus-badge-refresh"&&o()});chrome.runtime.onMessage.addListener((e,r,t)=>{if(e.type==="UPDATE_BADGE")return o().then(()=>t({success:!0})).catch(a=>{console.error("Badge update failed:",a),t({success:!1})}),!0});
